import 'package:flutter/material.dart';
class AppBottomNavBar extends StatelessWidget { const AppBottomNavBar({super.key, required this.farmer, required this.index, required this.onChanged}); final bool farmer; final int index; final ValueChanged<int> onChanged; @override Widget build(BuildContext context) { final labels = farmer ? ['Home', 'Listings', 'Orders', 'Earnings', 'Profile'] : ['Home', 'Search', 'Cart', 'Orders', 'Profile']; final icons = farmer ? [Icons.home_outlined, Icons.inventory_2_outlined, Icons.receipt_long_outlined, Icons.account_balance_wallet_outlined, Icons.person_outline] : [Icons.home_outlined, Icons.search, Icons.shopping_cart_outlined, Icons.receipt_long_outlined, Icons.person_outline]; return NavigationBar(selectedIndex: index, onDestinationSelected: onChanged, destinations: List.generate(labels.length, (i) => NavigationDestination(icon: Icon(icons[i]), label: labels[i]))); } }
